 393	    tq = tq_alloc(nb_streams, queue_size,
 394	                  (type == QUEUE_PACKETS) ? THREAD_QUEUE_PACKETS : THREAD_QUEUE_FRAMES);
 395	    if (!tq)
 396	        return AVERROR(ENOMEM);
