3516	        av_frame_unref(fgt.frame);
3517	        if (ret == AVERROR_EOF) {
3518	            av_log(fg, AV_LOG_VERBOSE, "Input %u no longer accepts new data\n",
3519	                   input_idx);
3520	            close_input(ifp);
3521	            continue;
3522	        }
3523	        if (ret < 0)
3524	            goto finish;
3525	
3526	read_frames:
