1858	static int send_to_enc_thread(Scheduler *sch, SchEnc *enc, AVFrame *frame)
1859	{
1860	    int ret;
1861	
1862	    if (!frame) {
1863	        tq_send_finish(enc->queue, 0);
1864	        return 0;
1865	    }
1866	
1867	    if (enc->in_finished)
1868	        return AVERROR_EOF;
1869	
1870	    ret = tq_send(enc->queue, 0, frame);
1871	    if (ret < 0)
1872	        enc->in_finished = 1;
1873	
1874	    return ret;
1875	}
