143	static int can_write(ThreadQueue *tq, unsigned int stream_idx)
144	{
145	    return tq->stream_count[stream_idx] < tq->queue_size;
146	}
147	
148	int tq_send(ThreadQueue *tq, unsigned int stream_idx, void *data)
149	{
150	    int *finished;
151	    int ret;
152	
153	    av_assert0(stream_idx < tq->nb_streams);
154	    finished = &tq->finished[stream_idx];
155	
156	    pthread_mutex_lock(&tq->lock);
157	
158	    if (*finished & FINISHED_SEND) {
159	        ret = AVERROR(EINVAL);
160	        goto finish;
161	    }
162	
163	    while (!(*finished & FINISHED_RECV) && !can_write(tq, stream_idx))
164	        pthread_cond_wait(&tq->cond_write[stream_idx], &tq->lock);
165	
166	    if (*finished & FINISHED_RECV) {
167	        ret = AVERROR_EOF;
168	        *finished |= FINISHED_SEND;
169	    } else {
170	        ret = av_fifo_write(tq->fifo_stream_index, &stream_idx, 1);
171	        if (ret < 0)
172	            goto finish;
173	
174	        ret = av_container_fifo_write(tq->fifo, data, 0);
175	        if (ret < 0)
176	            goto finish;
177	
178	        tq->stream_count[stream_idx]++;
179	        pthread_cond_broadcast(&tq->cond_read); // signal downstream
180	    }
181	
182	finish:
183	    pthread_mutex_unlock(&tq->lock);
184	
185	    return ret;
186	}
187	
188	static int receive_locked(ThreadQueue *tq, int *stream_idx,
189	                          void *data)
190	{
191	    unsigned int nb_finished = 0;
192	
193	    if (tq->choked)
194	        return AVERROR(EAGAIN);
195	
196	    while (av_container_fifo_read(tq->fifo, data, 0) >= 0) {
197	        unsigned idx;
198	        int ret;
199	
200	        ret = av_fifo_read(tq->fifo_stream_index, &idx, 1);
201	        av_assert0(ret >= 0);
202	
203	        // signal upstream if the fifo is no longer full
204	        if (tq->stream_count[idx]-- == tq->queue_size)
205	            pthread_cond_broadcast(&tq->cond_write[idx]);
206	
207	        if (tq->finished[idx] & FINISHED_RECV) {
208	            (tq->type == THREAD_QUEUE_FRAMES) ?
209	            av_frame_unref(data) : av_packet_unref(data);
210	            continue;
211	        }
212	
213	        *stream_idx = idx;
214	        return 0;
215	    }
216	
217	    for (unsigned int i = 0; i < tq->nb_streams; i++) {
218	        if (!tq->finished[i])
219	            continue;
220	
221	        /* return EOF to the consumer at most once for each stream */
222	        if (!(tq->finished[i] & FINISHED_RECV)) {
223	            tq->finished[i] |= FINISHED_RECV;
224	            *stream_idx   = i;
225	            return AVERROR_EOF;
226	        }
227	
228	        nb_finished++;
229	    }
230	
231	    return nb_finished == tq->nb_streams ? AVERROR_EOF : AVERROR(EAGAIN);
232	}
233	
234	int tq_receive(ThreadQueue *tq, int *stream_idx, void *data, int flags)
235	{
236	    int ret;
237	
238	    *stream_idx = -1;
239	
240	    pthread_mutex_lock(&tq->lock);
241	
242	    while (1) {
243	        ret = receive_locked(tq, stream_idx, data);
244	
245	        if (ret == AVERROR(EAGAIN) && !(flags & THREAD_QUEUE_FLAG_NO_BLOCK)) {
246	            pthread_cond_wait(&tq->cond_read, &tq->lock);
247	            continue;
248	        }
249	
250	        break;
251	    }
252	
253	    pthread_mutex_unlock(&tq->lock);
254	
255	    return ret;
256	}
257	
258	void tq_send_finish(ThreadQueue *tq, unsigned int stream_idx)
259	{
260	    av_assert0(stream_idx < tq->nb_streams);
261	
262	    pthread_mutex_lock(&tq->lock);
263	
264	    /* mark the stream as send-finished;
265	     * next time the consumer thread tries to read this stream it will get
266	     * an EOF and recv-finished flag will be set */
267	    tq->finished[stream_idx] |= FINISHED_SEND;
268	    tq->choked = 0;
269	    pthread_cond_broadcast(&tq->cond_read);
270	
271	    pthread_mutex_unlock(&tq->lock);
272	}
273	
274	void tq_receive_finish(ThreadQueue *tq, unsigned int stream_idx)
275	{
276	    av_assert0(stream_idx < tq->nb_streams);
277	
278	    pthread_mutex_lock(&tq->lock);
279	
280	    /* mark the stream as recv-finished;
281	     * next time the producer thread tries to send for this stream, it will
282	     * get an EOF and send-finished flag will be set */
283	    tq->finished[stream_idx] |= FINISHED_RECV;
284	    pthread_cond_broadcast(&tq->cond_write[stream_idx]);
285	
286	    pthread_mutex_unlock(&tq->lock);
287	}
288	
289	void tq_choke(ThreadQueue *tq, int choked)
290	{
291	    pthread_mutex_lock(&tq->lock);
292	
293	    int prev_choked = tq->choked;
294	    tq->choked = choked;
295	    if (choked != prev_choked)
296	        pthread_cond_broadcast(&tq->cond_read);
297	
298	    pthread_mutex_unlock(&tq->lock);
299	}

